negativeExample:
package org.eclipse.jface.internal.text.html;

public class HTMLPrinter {
    private static StringBuffer SHARED_BUFFER = new StringBuffer(100); // Field initialization, not a local var assignment

    public void appendToSharedBuffer(String text) {
        new StringBuffer(text).reverse(); // Not assigned to a local variable
    }

    public StringBuffer createBufferAndReturn(int capacity) {
        return new StringBuffer(capacity); // Return value, not a local var assignment
    }
}
